import re as _re
raw = str(bindings.get('domain_raw') or '').strip()
raw = _re.sub(r'[\"\'。、，《》（）\[\]\n\s]', '', raw).strip()
cats = bindings.get('domain_cats') or []
dmap = bindings.get('domain_map') or {}
chosen = ''
for c in cats:
    if raw == c or (raw and (raw in c or c in raw)):
        chosen = c
        break
if not chosen:
    # 兜底：部分领域名含连接词（与/和），去掉后子串匹配
    for c in cats:
        _key = c.replace('与', '').replace('和', '')
        if _key and _key in raw:
            chosen = c
            break
if chosen and chosen in dmap:
    bindings['domain'] = chosen
    bindings['resolved_tape_id'] = dmap[chosen]['tape_id']
    bindings['resolved_tape_name'] = dmap[chosen]['tape_name']
else:
    bindings['domain'] = ''
    bindings['resolved_tape_id'] = ''
    bindings['resolved_tape_name'] = ''

